    public function normalizeNullableType(Tokens $tokens, TypeAnalysis $typeAnalysis, bool $isQuestionMarkSyntax, ?ArgumentAnalysis $argumentAnalysis = null): void
    {
        $typeName = $typeAnalysis->getName();
        $typeStartIndex = $typeAnalysis->getStartIndex();
        $typeEndIndex = $typeAnalysis->getEndIndex();
        $isNullable = $typeAnalysis->isNullable();

        $startToken = $tokens[$typeStartIndex];
        $startContent = $startToken->getContent();
        $startId = $startToken->getId();
        $isStartArray = $startToken->isArray();

        if (!$isStartArray && null === $startId && '' === $startContent) {
            return;
        }

        $insideNamespaceScope = false;
        foreach ($tokens->getNamespaceDeclarations() as $namespaceAnalysis) {
            if (
                $typeStartIndex >= $namespaceAnalysis->getScopeStartIndex()
                && $typeStartIndex <= $namespaceAnalysis->getScopeEndIndex()
            ) {
                $insideNamespaceScope = true;

                break;
            }
        }

        if (!$insideNamespaceScope) {
            return;
        }

        if (null !== $argumentAnalysis) {
            $argumentName = $argumentAnalysis->getName();
            $argumentNameIndex = $argumentAnalysis->getNameIndex();

            if (null !== $argumentNameIndex && $typeEndIndex >= $argumentNameIndex) {
                return;
            }

            if (
                null !== $argumentName
                && null !== $argumentNameIndex
                && $tokens[$argumentNameIndex]->getContent() !== $argumentName
            ) {
                return;
            }
        }

        $type = $typeName;

        if (!str_contains($type, '|') && !str_contains($type, '&')) {
            $type = ($isNullable ? '?' : '').$type;
        }

        if ($isQuestionMarkSyntax) {
            $normalizedType = $this->convertToNullableType($type);
            $normalizedTypeAsString = implode('', $normalizedType);
        } else {
            $normalizedType = $this->convertToExplicitUnionType($type);
            $normalizedTypeAsString = implode('|', $normalizedType);
        }

        if ($normalizedTypeAsString === $type) {
            return; // nothing to fix
        }

        $tokens->overrideRange(
            $typeAnalysis->getStartIndex(),
            $typeAnalysis->getEndIndex(),
            $this->createTypeDeclarationTokens($normalizedType, $isQuestionMarkSyntax)
        );

        if (!$tokens[$typeAnalysis->getStartIndex() - 1]->equals('(')) {
            $tokens->ensureWhitespaceAtIndex($typeAnalysis->getStartIndex() - 1, 1, ' ');
        }

        $this->functionsAnalysis = [
            'tokens' => $tokens->getCodeHash() ?? '',
            'imports' => [],
            'declarations' => [],
        ];
    }

    /**
     * @return list<string>
     */
    private function convertToNullableType(string $type): array
    {
        if (str_starts_with($type, '?')) {
            return [$type]; // no need to convert; already fixed
        }

        return ['?', Preg::replace('/(?:\|null$|^null\|)/i', '', $type)];
    }

    /**
     * @return list<string>
     */
    private function convertToExplicitUnionType(string $type): array
    {
        if (str_contains($type, '|')) {
            return [$type]; // no need to convert; already fixed
        }

        return ['null', substr($type, 1)];
    }

    /**
     * @param list<string> $types
     *
     * @return list<Token>
     */
    private function createTypeDeclarationTokens(array $types, bool $isQuestionMarkSyntax): array
    {
        static $specialTypes = [
            '?' => CT::T_NULLABLE_TYPE,
            'array' => CT::T_ARRAY_TYPEHINT,
            'callable' => T_CALLABLE,
            'static' => T_STATIC,
        ];

        $count = \count($types);
        $newTokens = [];

        foreach ($types as $index => $type) {
            if (isset($specialTypes[strtolower($type)])) {
                $newTokens[] = new Token([$specialTypes[strtolower($type)], $type]);
            } else {
                foreach (explode('\\', $type) as $nsIndex => $value) {
                    if (0 === $nsIndex && '' === $value) {
                        continue;
                    }

                    if ($nsIndex > 0) {
                        $newTokens[] = new Token([T_NS_SEPARATOR, '\\']);
                    }

                    $newTokens[] = new Token([T_STRING, $value]);
                }
            }

            if ($index <= $count - 2 && !$isQuestionMarkSyntax) {
                $newTokens[] = new Token([CT::T_TYPE_ALTERNATION, '|']);
            }
        }

        return $newTokens;
    }
}

